class _ReraiseContextManager:
    """Supports both decorator and context manager usage."""
    def __init__(self, errors, into):
        self.errors = errors
        self.into = into

    def __enter__(self):
        pass

    def __exit__(self, exc_type, exc_val, exc_tb):
        if exc_type is None:
            return False
        if isinstance(self.errors, type) and issubclass(exc_type, self.errors):
            raise self.into from exc_val
        elif isinstance(self.errors, tuple):
            if exc_type in self.errors:
                raise self.into from exc_val
        return False

    def __call__(self, func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            try:
                return func(*args, **kwargs)
            except Exception as e:
                if isinstance(self.errors, type) and isinstance(e, self.errors):
                    raise self.into from e
                elif isinstance(self.errors, tuple):
                    if type(e) in self.errors:
                        raise self.into from e
                raise
        return wrapper


def reraise(errors, into):
    """Decorator or context manager that converts exceptions.

    As a decorator:
        @reraise(ValueError, MyError)
        def foo(): ...

    As a context manager:
        with reraise(ValueError, MyError):
            ...
    """
    return _ReraiseContextManager(errors, into)

