def reraise(errors, into):
    """Decorator or context manager that converts exceptions.

    As a decorator:
        @reraise(ValueError, MyError)
        def foo(): ...

    As a context manager:
        with reraise(ValueError, MyError):
            ...
    """
    if hasattr(errors, '__iter__') and not isinstance(errors, type):
        # It's a tuple/list of error types
        def decorator(func):
            @wraps(func)
            def wrapper(*args, **kwargs):
                try:
                    return func(*args, **kwargs)
                except Exception as e:
                    if type(e) in errors:
                        raise into from e
                    raise
            return wrapper
        return decorator
    else:
        # Single error type
        def decorator(func):
            @wraps(func)
            def wrapper(*args, **kwargs):
                try:
                    return func(*args, **kwargs)
                except Exception as e:
                    if isinstance(e, errors):
                        raise into from e
                    raise
            return wrapper
        return decorator
